export function bm(p,id){const bq=p.bikeQuiz[id];if(!bq)return 0;let t=0;["easy","medium","hard"].forEach(d=>{if(bq[d])t+=bq[d].best});return Math.round(t/15*100)}
export function om(p){let s=0;BIKES.forEach(b=>{s+=bm(p,b.id)});return Math.round(s/BIKES.length)}
export function bs(p,id){const bq=p.bikeQuiz[id];if(!bq)return null;for(let i=2;i>=0;i--){const d=["easy","medium","hard"][i];if(bq[d]&&bq[d].best===bq[d].total)return`${d} done`;if(bq[d])return`${d} started`}return null}
export function nb(id){const i=BIKES.findIndex(b=>b.id===id);return i<BIKES.length-1?BIKES[i+1]:null}
